def separate_shap_values_by_predicted_class(shap_values, predicted_probabilities, sample_features):
    # Assuming shap_values shape is (num_samples, num_features, num_classes)
    # and predicted_probabilities shape is (num_samples, num_classes)
    # and sample_features shape is (num_samples, num_features)
    class_shap_values = {}
    for i in range(shap_values.shape[0]):
        # Get the index of the class with the highest probability for the i-th sample
        class_index = np.argmax(predicted_probabilities[i])
        # Check if the class_index is already in the dictionary
        if class_index not in class_shap_values:
            class_shap_values[class_index] = {'shap_values': [], 'features': []}
        # Append the SHAP values and the corresponding features for the i-th sample and the predicted class
        class_shap_values[class_index]['shap_values'].append(shap_values[i, :, class_index])
        class_shap_values[class_index]['features'].append(sample_features[i])

    # Convert lists to numpy arrays
    for class_index in class_shap_values:
        class_shap_values[class_index]['shap_values'] = np.array(class_shap_values[class_index]['shap_values'])
        class_shap_values[class_index]['features'] = np.array(class_shap_values[class_index]['features'])

    return class_shap_values
